coding.solution:
import re

def regex_extract(body, name, regex, template, match_no, default):
    matches = list(re.finditer(regex, body))
    def fill(m):
        return re.sub(r'\$(\d+)\$', lambda g: m.group(int(g.group(1))) or '', template)
    if match_no == -1:
        if not matches:
            return {name: default, name + '_matchNr': '0'}
        out = {f'{name}_{i}': fill(m) for i, m in enumerate(matches, 1)}
        out[name + '_matchNr'] = str(len(matches))
        return out
    if 1 <= match_no <= len(matches):
        return {name: fill(matches[match_no - 1])}
    return {name: default}

