import re

def response_assertion(text, rule, patterns, negate=False):
    def check(p):
        if rule == 'substring':
            return p in text
        if rule == 'equals':
            return text == p
        if rule == 'contains':
            return re.search(p, text) is not None
        if rule == 'matches':
            return re.fullmatch(p, text) is not None
        raise ValueError(rule)
    return all(check(p) != negate for p in patterns)

