coding.solution:
import re

def json_path(obj, path):
    tokens = re.findall(r'\.(\w+)|\[(\*|\d+)\]', path[1:])
    current = [obj]
    for key, idx in tokens:
        nxt = []
        for c in current:
            if key:
                if isinstance(c, dict) and key in c:
                    nxt.append(c[key])
            elif idx == '*':
                if isinstance(c, list):
                    nxt.extend(c)
            else:
                i = int(idx)
                if isinstance(c, list) and 0 <= i < len(c):
                    nxt.append(c[i])
        current = nxt
    return current
